 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # These tasks encode one binary pattern twice, separated by blank rows.
    # Highlight the blank cells of the lower copy where the first copy has
    # occupied cells; preserve the source shapes and background elsewhere.
    active=[r for r,row in enumerate(grid) if any(v!=9 for v in row)]
    bands=[]
    if active:
        s=p=active[0]
        for r in active[1:]:
            if r>p+1:
                bands.append((s,p)); s=r
            p=r
        bands.append((s,p))
    if len(bands)>=2:
        (a,b),(c,d)=bands[0],bands[-1]
        height=min(b-a+1,d-c+1)
        width=w
        # Search translations that best align the two binary patterns.
        # The extra pattern is the portion of the top object absent from bottom.
        best=None
        for dr in range(-h,h+1):
            for dc in range(-w,w+1):
                same=diff=0
                for r in range(c,d+1):
                    for col in range(w):
                        rr=r+dr; cc=col+dc
                        if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=9:
                            if grid[r][col]!=9: same+=1
                            else: diff+=1
                score=same-diff
                if best is None or score>best[0]: best=(score,dr,dc)
        # Common pattern is not colored; color cells where projected source
        # content is present but the target is background.
        if best:
            _,dr,dc=best
            for r in range(c,d+1):
                for col in range(w):
                    rr=r+dr; cc=col+dc
                    if 0<=rr<h and 0<=cc<w and grid[rr][cc]!=9 and grid[r][col]==9:
                        out[r][col]=1
    return out
