        bands.append((s,p))
    if len(bands)>=2:
        s,e=bands[-1]
        # Find the vertical pattern region: repeated 2-wide groups of 8s with
        # two-column gaps. It starts after the lower shape's left component.
        # Fill missing cells within the right-hand area of the lower block.
        # Use periodicity along columns and row density to locate this region.
        candidates=[]
        for start in range(w):
            score=0
            for c in range(start,w):
                if (c-start)//2 % 2==0:
                    score += sum(grid[r][c]==8 for r in range(s,e+1))
            if score>0: candidates.append((score,start))
        # Choose smallest start among starts attaining max periodic score.
        start=max(candidates)[1] if candidates else w
