            # in the column immediately adjacent to repeated 8-bearing cols.
            if c>=w//2 and any(grid[r][c]==8 for r in range(s,e+1)):
                for r in range(s,e+1):
                    if grid[r][c]==9 and (r==s or grid[r-1][c]==8 or (r+1<=e and grid[r+1][c]==8)):
