    # Look for columns with at least one 8, to identify the barcode region.
    # Barcode spacing in these tasks is a repeating 2-column rhythm: two
    # pattern columns with 8s, then two separator columns.
    cols = [c for c in range(w) if any(grid[r][c] == 8 for r in range(h))]
    if not cols:
        return out
    # Find the rightmost contiguous-ish region of repeated 8-pairs.
    # This is a row/column motif, so detect the strongest 4-periodic phase.
    best = None
    for start in range(w):
        for phase in range(4):
            score = 0
            for r in range(h):
                for c in range(start, w):
                    if grid[r][c] == 8 and (c - phase) % 4 < 2:
                        score += 1
            if best is None or score > best[0]:
                best = (score, start, phase)
    if best:
        _, start, phase = best
        # Determine the lower motif's rows (separated from upper by blank gap).
        active = [r for r in range(h) if any(v != 9 for v in grid[r])]
        gaps = [r for r in range(h) if not any(v != 9 for v in grid[r])]
        if active:
            lower = max(active)
            first_lower = min(r for r in active if r > (h//2)) if any(r > h//2 for r in active) else lower
            for r in range(first_lower, lower + 1):
                for c in range(start, w):
                    if grid[r][c] == 9 and (c - phase) % 4 < 2:
                        # only fill when adjacent columns show 8s in the same band
                        if (c > 0 and grid[r][c-1] == 8) or (c+1 < w and grid[r][c+1] == 8):
                            out[r][c] = 1
    return out
