 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find each foreground component (8s) without crossing diagonal gaps.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy, xx = y+dy, x+dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 8 and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                comps.append(cells)

    # Each large object has separate small repeated components. The region to
    # color is the 8x-style long row/column pattern that continues the final
    # component into blank cells, with the copy indicated by the other object.
    # We identify the isolated 8s arranged as a repeated sequence across width.
    for r in range(h):
        # A full continuous row of foreground defines the left extent of the
        # repeated feature. If it runs across most of the row, propagate its
        # color to matching blank cells in the paired, lower pattern.
        run = 0
        longest = (0, -1)
        for c, v in enumerate(grid[r]):
            run = run + 1 if v == 8 else 0
            if run > longest[0]: longest = (run, c)
        if longest[0] >= max(8, w//3):
            end = longest[1]
            # Extend the stroke according to the periodic 2-on/2-off barcode
            # visible elsewhere: fill only the first two cells of each 4-cycle.
            for c in range(end+1, w):
                if (c-(end+1)) % 4 < 2 and grid[r][c] == 9:
                    out[r][c] = 1

    # The sparse lower object contains the same horizontal stripe with holes:
    # where two 8s on a row are separated by a single background cell, color
    # that missing cell as the repeated pattern's continuation.
    for r in range(h):
        for c in range(1, w-1):
            if grid[r][c] == 9 and grid[r][c-1] == 8 and grid[r][c+1] == 8:
                out[r][c] = 1
    return out
