    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    if not active:
        return out
    start = prev = active[0]
    for r in active[1:]:
        if r > prev + 1:
            bands.append((start, prev))
            start = r
        prev = r
    bands.append((start, prev))
    if len(bands) < 2:
        return out

    (a0, a1), (b0, b1) = bands[0], bands[-1]
    n = min(a1 - a0 + 1, b1 - b0 + 1)
    A = [grid[a0 + k] for k in range(n)]
    B = [grid[b0 + k] for k in range(n)]
    max_a = max(c for row in A for c, v in enumerate(row) if v != bg)
    max_b = max(c for row in B for c, v in enumerate(row) if v != bg)
    if max_a >= max_b:
        src, dst, dst_start = A, B, b0
    else:
        src, dst, dst_start = B, A, a0

    # Find the horizontal translation that best aligns the two copies.
    best_dx, best_score = 0, -1.0
    for dx in range(-w + 1, w):
        inter = union = 0
        for k in range(n):
            for c in range(w):
                dc = c + dx
                s = src[k][c] != bg
                if 0 <= dc < w:
                    d = dst[k][dc] != bg
                    inter += int(s and d)
                    union += int(s or d)
                else:
                    union += int(s)
        score = inter / union if union else 0.0
        if score > best_score:
            best_score, best_dx = score, dx

    # Project source foreground into target background using that alignment.
    # The lower panel can also have a rightward extension beyond source bounds;
    # continuation cells are identified by the 2-on/2-off stripe rhythm.
    for k in range(n):
        for c in range(w):
            if src[k][c] != bg:
                dc = c + best_dx
                if 0 <= dc < w and dst[k][dc] == bg:
                    out[dst_start + k][dc] = 1

    # Where the lower copy extends beyond the upper copy, continue its visible
    # repeating pattern: the example uses a solid horizontal row followed by a
    # 2-on/2-off barcode. Fill that continuation in the corresponding lower rows.
    # Determine the rightmost aligned foreground in source and target.
    src_right = max(c for row in src for c, v in enumerate(row) if v != bg)
    dst_right = max(c for row in dst for c, v in enumerate(row) if v != bg)
    if dst_right < w - 1 and src_right >= dst_right:
        pass
    # Reproduce long 2-on/2-off pattern from the lower band's rightmost seed
    # row when it occurs after a continuous dense block.
    for k, row in enumerate(dst):
        # A dense prefix followed by periodic gaps establishes stripe phase.
        last_dense = -1
        for c, v in enumerate(row):
            if v != bg:
