 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the two non-background panels, separated by blank rows.
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    if not active:
        return out
    bands = []
    start = prev = active[0]
    for r in active[1:]:
        if r > prev + 1:
            bands.append((start, prev))
            start = r
        prev = r
    bands.append((start, prev))
    if len(bands) < 2:
        return out

    (a0, a1), (b0, b1) = bands[0], bands[-1]
    n = min(a1 - a0 + 1, b1 - b0 + 1)
    A = [grid[a0 + k] for k in range(n)]
    B = [grid[b0 + k] for k in range(n)]
    max_a = max(c for row in A for c, v in enumerate(row) if v != bg)
    max_b = max(c for row in B for c, v in enumerate(row) if v != bg)
    if max_a >= max_b:
        src, dst, dst_start = A, B, b0
    else:
        src, dst, dst_start = B, A, a0

    # Complete the shorter panel to the right, row by row. Align each pair
    # using the foreground overlap (small shifts occur in the repeated raster).
    for k in range(n):
        dst_right = max((c for c, v in enumerate(dst[k]) if v != bg), default=-1)
        best_shift, best_overlap = 0, -1
        for shift in range(-3, 4):
            overlap = 0
            for c, v in enumerate(src[k]):
                dc = c + shift
                if v != bg and 0 <= dc < w and dst[k][dc] != bg:
                    overlap += 1
            if overlap > best_overlap or (overlap == best_overlap and abs(shift) < abs(best_shift)):
                best_overlap, best_shift = overlap, shift

        # Copy foreground beyond the target's current right edge.
        for c, v in enumerate(src[k]):
            dc = c + best_shift
            if dc > dst_right and dc < w and v != bg and dst[k][dc] == bg:
                out[dst_start + k][dc] = 1

        # If the source has a solid foreground run reaching the right boundary,
        # continue that run through the target's remaining right-hand space.
        run = 0
        for c in range(w - 1, -1, -1):
            if src[k][c] != bg:
                run += 1
            else:
                break
        if run >= 3 and dst_right < w - 1:
            for c in range(dst_right + 1, w):
                if dst[k][c] == bg:
                    out[dst_start + k][c] = 1
    return out
